    // Les agendas en ligne, suite
    'agenda.portee_refusee' => 'Die Berechtigung deckt deinen Kalender nicht ab.',
    'agenda.portee_refusee_aide' => 'Verbinde dich erneut und kreuze auf dem Zustimmungsbildschirm das Kalender-Kästchen an — es ist nicht vorangekreuzt. Ohne es kann die Anwendung dich erkennen, sieht aber keinen Termin.',
    'agenda.reconnecter' => 'Mein Konto neu verbinden',
    'agenda.partages_refuses' => 'Wenn {nom} die geteilten Kalender ablehnt, liegt es an der Berechtigung.',
    'agenda.partages_refuses_aide.un' => 'Du folgst {n} von jemand anderem geteilten Kalender, und deine Berechtigung stammt aus der Zeit, bevor die Anwendung sie lesen konnte. Versuch es: je nach Konto klappt es. Wird das Lesen abgelehnt, autorisiere die Anwendung erneut — der Knopf ist weiter unten.',
    'agenda.partages_refuses_aide.plusieurs' => 'Du folgst {n} von anderen geteilten Kalendern, und deine Berechtigung stammt aus der Zeit, bevor die Anwendung sie lesen konnte. Versuch es: je nach Konto klappt es. Wird das Lesen abgelehnt, autorisiere die Anwendung erneut — der Knopf ist weiter unten.',
    'agenda.synchroniser_premiere' => 'Meinen Kalender abgleichen',
    'agenda.synchroniser' => 'Jetzt abgleichen',
    'agenda.auto_aide' => 'Der Abgleich läuft <strong>von selbst</strong>, wenn du die Anwendung öffnest, sofern der letzte mehr als fünf Minuten her ist. Der Knopf bleibt, damit du nicht warten musst und die Meldung bei einer Ablehnung siehst.',
    'agenda.vers_ici' => '<strong>Von {nom} hierher:</strong> die unten angekreuzten Kalender, vom vergangenen Monat bis zum kommenden Jahr, Serien eingeschlossen — und „Mes Cours“ selbst, damit das, was du dort von {nom} aus anlegst, hier ankommt.',
    'agenda.modifs_ici' => '<strong>Was du hier änderst oder löschst</strong>, ändert sich auch in {nom}, aber <strong>nur in den Kalendern, die dir gehören</strong> — deinen und „Mes Cours“. Stammt der Termin aus einem Kalender, den dir jemand geteilt hat, lässt er sich hier bearbeiten, ohne dort etwas zu ändern, und der nächste Abgleich stellt die dortige Fassung wieder her. Die Anwendung schreibt von sich aus nichts bei anderen.',
    'agenda.exception' => '<strong>Eine Ausnahme, und du löst sie aus:</strong> jeder Termin kann den Kalender nennen, in den er geht, auch den von jemandem, der dir Schreibrecht gegeben hat. Es ist keine erstarrte Kopie — der Termin bleibt dort deiner, und was du hier damit machst, folgt ihm dorthin.',
    'agenda.ici_vers' => '<strong>Von hier nach {nom}:</strong> die Fristen deiner offenen Aufgaben und die Termine, die keinen anderen Kalender nennen, in <strong>„{dest}“</strong>{cree}. Nur dorthin schreibt sie. Eine erledigte Aufgabe verlässt den Kalender, und ein hier gelöschter Termin verschwindet dort.',
    'agenda.cree_chez' => ', ein Kalender, den die Anwendung in {nom} anlegt',
    'agenda.destination_sur' => 'Den Zielkalender wechseln? Was die Anwendung in den aktuellen gelegt hat, wird entfernt und in den neuen gelegt.',
    'agenda.destination' => 'Der Kalender, der deine Termine empfängt',
    'agenda.destination_appli' => 'Mes Cours — der Kalender der Anwendung',
    'agenda.principal_suffixe' => ' — dein Hauptkalender',
    'agenda.destination_aide' => 'Es werden nur deine eigenen Kalender angeboten. Einen zu benennen schüttet deine Termine und die Fristen deiner Aufgaben hinein: praktisch für einen Kalender, den andere ansehen, sofern du genau das dort zeigen willst.',
    'agenda.changer_destination' => 'Ziel ändern',
    'agenda.retirer_importes_sur' => 'Die Termine {de} aus dem Kalender entfernen? Sie bleiben in deinem Kalender.',
    'agenda.retirer_importes' => 'Die importierten Termine entfernen',
    'agenda.retirer_envoi_sur' => 'Entfernen, was die Anwendung {de} abgelegt hat? Deine Termine und Aufgaben bleiben hier unberührt.',
    'agenda.retirer_envoi' => 'Meine Termine {de} entfernen',
    'agenda.delier_sur' => 'Dein {nom}-Konto trennen? Die Anwendung greift dann nicht mehr auf deinen Kalender zu, und die importierten Termine verlassen diesen.',
    'agenda.delier' => 'Mein Konto trennen',
    'agenda.relier_titre' => 'Dein Konto verbinden',
    'agenda.relier_aide' => 'Deine {nom}-Termine und -Kurse kommen in den Kalender der Anwendung, und deine Termine von hier kommen in deinen.',
    'agenda.connecter' => 'Mein {nom}-Konto verbinden',
    'agenda.connecter_aide' => '{nom} bittet dich, dein Konto zu wählen und den Zugriff auf deinen Kalender zu erlauben, und bringt dich dann hierher zurück. Du kannst das Konto jederzeit trennen.',
    'agenda.calendriers_titre' => 'Die zu lesenden Kalender',
    'agenda.partage_ancien' => 'Deine Berechtigung stammt aus der Zeit, bevor die Anwendung nach <strong>von anderen geteilten</strong> Kalendern fragte. Sie ist nicht immer nötig — je nach Konto gibt {nom} sie ohne Weiteres. Wird dir einer verweigert, autorisiere erneut: nichts geht verloren, weder deine Verbindung noch deine Termine.',
    'agenda.reautoriser' => 'Anwendung erneut autorisieren',
    'agenda.aucun_calendrier' => 'Die Anwendung hat nur deinen Hauptkalender gelesen. Frage {nom} nach der vollständigen Liste, um die anderen zu wählen.',
    'agenda.calendrier' => 'Kalender',
    'agenda.principal' => 'Haupt',
    'agenda.partage_par' => 'geteilt von {qui}',
    'agenda.quelquun' => 'jemandem',
    'agenda.enregistrer_choix' => 'Meine Auswahl speichern',
    'agenda.voir_calendriers' => 'Meine Kalender ansehen',
    'agenda.actualiser' => 'Liste aktualisieren',
    'agenda.ce_que_voit' => 'Was die Anwendung sieht',
    'agenda.ce_que_voit_1' => 'Deinen Kalender, und sonst nichts: sie bittet um die Erlaubnis, deine Termine, deinen Namen und deine Adresse zu lesen und zu schreiben. Nicht deine Nachrichten, nicht deine Dateien, nicht deine Kontakte.',
    'agenda.ce_que_voit_2' => 'Die erhaltene Berechtigung wird in der Datenbank der Anwendung gehalten. Sie ist <strong>von exportierbaren Sicherungen ausgenommen</strong>, und das Trennen deines Kontos löscht sie.',
    'agenda.pour_hebergeur' => 'Für die Person, die die Anwendung betreibt',
    // Les agendas : l’inscription chez le fournisseur
    'agenda.inscription_unique' => 'Eine einzige Registrierung genügt für alle. Sie wird in <code>config/parametres.php</code> gesetzt, Abschnitt <code>{section}</code>, der nicht ins Repository geht.',
    'agenda.ms_1' => 'Auf <a href="https://entra.microsoft.com" target="_blank" rel="noopener">entra.microsoft.com</a>: <em>Anwendungen</em> › <em>App-Registrierungen</em> › <em>Neue Registrierung</em>.',
    'agenda.ms_2' => 'Unterstützte Kontotypen: <em>Konten in einem beliebigen Organisationsverzeichnis und persönliche Microsoft-Konten</em>.',
    'agenda.ms_3' => 'Weiterleitungs-URI — trage genau diese ein:',
    'agenda.ms_4' => 'Plattform: <strong>Mobile- und Desktopanwendungen</strong> lokal, ohne Geheimnis; <strong>Web</strong> im Netz, mit einem Clientgeheimnis.',
    'agenda.ms_5' => 'Trage die <strong>Anwendungs-ID (Client)</strong> in <code>outlook.client_id</code> ein.',
    'agenda.g_1' => 'Auf <a href="https://console.cloud.google.com" target="_blank" rel="noopener">console.cloud.google.com</a>: lege ein Projekt an und aktiviere <em>Google Calendar API</em>.',
    'agenda.g_2' => '<em>Datenzugriff</em>: füge die Berechtigung <code>https://www.googleapis.com/auth/calendar</code> hinzu, und nur diese.',
    'agenda.g_3' => '<em>Zielgruppe</em>: trage deine Adresse unter <em>Testnutzer</em> ein, oder veröffentliche die Anwendung — sonst lehnt Google sogar dein eigenes Konto ab.',
    'agenda.g_4' => '<em>Clients</em>: ein OAuth-Client vom Typ <strong>Webanwendung</strong>, mit genau dieser Weiterleitungsadresse:',
    'agenda.g_5' => 'Trage die <strong>Client-ID</strong> und das <strong>Geheimnis</strong> in <code>google.client_id</code> und <code>google.secret</code> ein — Google verlangt beides, auch lokal.',
    'agenda.g_test' => 'Solange die Anwendung bei Google „im Test“ bleibt, läuft die Berechtigung nach sieben Tagen ab und du musst dich neu verbinden. Sie zu veröffentlichen — ein Knopf, ohne Prüfung und ohne Warten — hebt diese Frist auf; der Warnbildschirm bleibt bis zur Prüfung.',
    'agenda.en_ligne' => 'Online trage auch <code>{section}.adresse_retour</code> ausdrücklich ein: was ein Browser als Host angibt, glaubt man nicht aufs Wort, und diese Adresse muss der dort angegebenen entsprechen.',
    // Les messages des agendas
