    'cpt.transcription_aide' => 'Eingeschaltet schreibt dein Browser mit, was du beim Aufnehmen sagst, und deine Freunde lesen den Text unter der Sprachnachricht. Chrome und Edge senden dafür den Ton an Google oder Microsoft; Firefox kann nicht transkribieren. Ausgeschaltet gehen deine Sprachnachrichten ohne Text. Bereits gesendete ändern sich nicht.',
